use vstd::prelude::*;

verus! {
    fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
        requires
            !list.is_empty(),
            1 <= k < list.len(),
        ensures
            new_list.len() == list.len() - 1,
            forall |i: usize| (i < k - 1 ==> new_list[i] == list[i]) &&
                             (i >= k - 1 ==> new_list[i] == list[i + 1]),
    {
        let n = list.len();
        let mut new_list: Vec<i32> = Vec::new();
        let mut i: usize = 0;

        while i < n
            invariant
                new_list.len() == i,
                i <= n,
                forall |j: usize| (j < i ==> new_list[j] == list[j]) &&
                                  (j >= k - 1 ==> new_list[j] == list[j + 1]),
            decreases n - i,
        {
            if i == k - 1 {
                // Skip the k-th element
                i = i + 1;
                continue;
            }
            new_list.push(list[i]);
            i = i + 1;
        }
        new_list
    }
}
